<?php

declare(strict_types=1);

namespace WPLokerBJM\Core\Container\Attributes;

use Attribute;

/**
 * Base class for all WordPress hook attributes.
 * @template TParams
 */
abstract class BaseHookAttribute
{
    /**
     * Types autocomplete DX generated by generate-meta-hooks.php
     *
     * @param string|(\Closure(TParams...): string) $hook
     * @param int $priority
     * @param int $acceptedArgs
     * @param bool $deferRegister defer activation (forced true when $deferRegisterUntilHook is set)
     * 
     * @param (\Closure(TParams...): bool)|null $executeIf decide whether to execute callback, potentially instantiating the object
     * 
     * @param (\Closure(TParams...): bool)|null $registerIf decide whether to register the hook
     * 
     * @param array<int, string|\BackedEnum|\Closure(TParams...): array> $tag
     * 
     * @param string|(\Closure(TParams...): string)|null $deferRegisterUntilHook
     * !defer registration until the named 'action' trigger hook fires (implies defer); a Closure is resolved through the container and must return the trigger hook name
     * @param bool $once consume-on-any-evaluation: the registration removes itself after executeIf is evaluated or callback proceeded
     */
    public function __construct(
        public readonly string|\Closure $hook,
        public readonly int $priority = 10,
        public readonly int $acceptedArgs = 1,
        public readonly ?\Closure $executeIf = null,
        public readonly ?\Closure $registerIf = null,
        public readonly array|\Closure $tag = [],
        public readonly string|\Closure|null $deferRegisterUntilHook = null,
        public bool $deferRegister = false,
        public readonly bool $once = false,
    ) {
        $this->deferRegister = $deferRegisterUntilHook !== null ? true : $deferRegister;
    }
}

/**
 * Attribute for WordPress actions.
 */
#[Attribute(Attribute::TARGET_METHOD | Attribute::TARGET_PROPERTY | Attribute::IS_REPEATABLE)]
class Action extends BaseHookAttribute {}
/**
 * Attribute for WordPress actions.
 * @template TParams of object
 */
#[Attribute(Attribute::TARGET_METHOD | Attribute::TARGET_PROPERTY | Attribute::IS_REPEATABLE)]
class Filter extends BaseHookAttribute {}
